<?php
require_once __DIR__.'/bootstrap.php';require_admin();$section=(string)($_GET['sec']??'historia');if(!in_array($section,['historia','escolha','usuarios'],true))$section='historia';$lang=(int)($_GET['lang']??1);$lang=$lang===2?2:1;
$table=$section==='escolha'?($lang===2?'escolhasen':'escolhas'):($lang===2?'historiaen':'historia');$pk=$section==='escolha'?'id_escolha':'id_historia';
$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$action=(string)($_POST['action']??'');
 try{
 if($section==='usuarios'){throw new RuntimeException('A listagem de jogadores é somente leitura.');}
 if($section==='historia'){
  $id=(int)($_POST['id_historia']??0);$texto=trim((string)($_POST['texto']??''));$cenario=basename((string)($_POST['cenario']??''));$personagem=basename((string)($_POST['personagem']??''));$nome=trim((string)($_POST['nome']??''));$video=basename((string)($_POST['video']??''));$musica=in_array((string)($_POST['musica']??''),['','1'],true)?(string)($_POST['musica']??''):'';$animacao=(int)($_POST['animacao']??0);$animacao=$animacao===1?1:0;
  if($action==='delete'){$st=db()->prepare("DELETE FROM $table WHERE id_historia=?");$st->bind_param('i',$id);$st->execute();}
  else {if($action==='create'){$st=db()->prepare("INSERT INTO $table(id_historia,texto,cenario,personagem,musica,nome,video,animacao) VALUES(?,?,?,?,?,?,?,?)");$st->bind_param('issssssi',$id,$texto,$cenario,$personagem,$musica,$nome,$video,$animacao);$st->execute();}else{$st=db()->prepare("UPDATE $table SET texto=?,cenario=?,personagem=?,musica=?,nome=?,video=?,animacao=? WHERE id_historia=?");$st->bind_param('ssssssii',$texto,$cenario,$personagem,$musica,$nome,$video,$animacao,$id);$st->execute();}}
 }else{
 $id=(int)($_POST['id_escolha']??0);$source=(int)($_POST['id_historia']??0);$dest=(int)($_POST['id_destino']??0);$text=trim((string)($_POST['escolha']??''));$npc=(int)($_POST['id_usuario']??1);
 if($action==='delete'){$st=db()->prepare("DELETE FROM $table WHERE id_escolha=?");$st->bind_param('i',$id);$st->execute();}elseif($action==='create'){$st=db()->prepare("INSERT INTO $table(id_escolha,id_usuario,escolha,id_destino,id_historia) VALUES(?,?,?,?,?)");$st->bind_param('iisii',$id,$npc,$text,$dest,$source);$st->execute();}else{$st=db()->prepare("UPDATE $table SET id_usuario=?,escolha=?,id_destino=?,id_historia=? WHERE id_escolha=?");$st->bind_param('isiii',$npc,$text,$dest,$source,$id);$st->execute();}
 }
 redirect('admin.php?sec='.urlencode($section).'&lang='.$lang.'&ok=1');
 }catch(Throwable $e){$error='Não foi possível salvar. Verifique IDs, limites de texto (255 caracteres) e relacionamentos entre cenas.';}
}
$edit=(int)($_GET['edit']??-99999);$item=null;if($section!=='usuarios' && $edit!==-99999){$st=db()->prepare("SELECT * FROM $table WHERE $pk=?");$st->bind_param('i',$edit);$st->execute();$item=$st->get_result()->fetch_assoc()?:null;}
if($section==='usuarios'){$items=db()->query('SELECT id_usuario,nome,email,imagem FROM usuario WHERE id_usuario>1 ORDER BY id_usuario DESC LIMIT 100')->fetch_all(MYSQLI_ASSOC);}else{$items=db()->query("SELECT * FROM $table ORDER BY $pk DESC LIMIT 300")->fetch_all(MYSQLI_ASSOC);}
page_start('Estúdio'); ?>
<main class="dashboard"><div class="dashboard-heading"><div><span class="eyebrow">ÁREA ADMINISTRATIVA</span><h1>Estúdio de histórias</h1><p class="muted">Edite as cenas e decisões sem sair do universo do jogo.</p></div><a class="btn ghost" href="menu.php">← Voltar ao jogo</a></div><div class="tabs"><a href="?sec=historia&amp;lang=<?=$lang?>" class="<?=$section==='historia'?'active':''?>">Cenas</a><a href="?sec=escolha&amp;lang=<?=$lang?>" class="<?=$section==='escolha'?'active':''?>">Escolhas</a><a href="?sec=usuarios" class="<?=$section==='usuarios'?'active':''?>">Jogadores</a></div><?php if($section!=='usuarios'):?><div class="language"><a class="<?=$lang===1?'selected':''?>" href="?sec=<?=h($section)?>&lang=1">Português</a><a class="<?=$lang===2?'selected':''?>" href="?sec=<?=h($section)?>&lang=2">English</a></div><?php endif;?><?php if($error):?><p class="alert"><?=h($error)?></p><?php endif;?><?php if(isset($_GET['ok'])):?><p class="muted">✓ Alterações salvas.</p><?php endif;?>
<?php if($section!=='usuarios'):?><section class="panel"><h2><?= $item?'Editar':'Criar' ?> <?= $section==='historia'?'cena':'escolha' ?></h2><form class="editor-form" method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="<?=$item?'update':'create'?>"><div class="editor-row"><label>ID <?= $section==='historia'?'da cena':'da escolha' ?><input type="number" name="<?=h($pk)?>" required value="<?=h((string)($item[$pk]??''))?>" <?=$item?'readonly':''?>></label><?php if($section==='escolha'):?><label>Cena de origem<input type="number" name="id_historia" value="<?=h((string)($item['id_historia']??''))?>" required></label><?php else:?><label>Nome de quem fala<input name="nome" maxlength="255" value="<?=h($item['nome']??'')?>"></label><?php endif;?></div>
<?php if($section==='historia'):?><label>Texto da cena<textarea name="texto" maxlength="255"><?=h($item['texto']??'')?></textarea></label><div class="editor-row"><label>Imagem do cenário (arquivo em img/)<input name="cenario" value="<?=h($item['cenario']??'')?>" required></label><label>Imagem do personagem<input name="personagem" value="<?=h($item['personagem']??'')?>"></label><label>Vídeo (opcional)<input name="video" value="<?=h($item['video']??'')?>"></label><label>Música<select name="musica"><option value="">Desligada</option><option value="1" <?=($item['musica']??'')==='1'?'selected':''?>>Trilha principal</option></select></label><label>Texto animado<select name="animacao"><option value="0">Sim</option><option value="1" <?=($item['animacao']??0)==1?'selected':''?>>Não</option></select></label></div>
<?php else:?><label>Texto da decisão<textarea name="escolha" maxlength="255" required><?=h($item['escolha']??'')?></textarea></label><div class="editor-row"><label>ID da cena de destino<input type="number" name="id_destino" required value="<?=h((string)($item['id_destino']??''))?>"></label><label>ID do personagem associado (1 = protagonista)<input type="number" name="id_usuario" required value="<?=h((string)($item['id_usuario']??1))?>"></label></div><?php endif;?><div class="editor-actions"><button class="btn primary" type="submit">Salvar alterações</button><?php if($item):?><a class="mini-btn" href="?sec=<?=h($section)?>&lang=<?=$lang?>">Cancelar edição</a><?php endif;?></div></form></section><?php endif;?>
<section class="panel"><h2><?= $section==='usuarios'?'Jogadores cadastrados':($section==='historia'?'Cenas existentes':'Escolhas existentes') ?></h2><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th><?= $section==='usuarios'?'Nome':'Conteúdo' ?></th><th><?= $section==='usuarios'?'Email':($section==='historia'?'Cenário':'Origem → Destino') ?></th><?php if($section!=='usuarios'):?><th>Ações</th><?php endif;?></tr></thead><tbody><?php foreach($items as $r):?><tr><td><?=h((string)($r[$section==='usuarios'?'id_usuario':$pk]??''))?></td><td><?=h((function_exists('mb_strimwidth')?mb_strimwidth((string)($r[$section==='usuarios'?'nome':($section==='historia'?'texto':'escolha')]??''),0,125,'…'):substr((string)($r[$section==='usuarios'?'nome':($section==='historia'?'texto':'escolha')]??''),0,125)))?></td><td><?=h($section==='usuarios'?($r['email']??''):($section==='historia'?($r['cenario']??''):($r['id_historia'].' → '.$r['id_destino'])))?></td><?php if($section!=='usuarios'):?><td><div class="editor-actions"><a class="mini-btn" href="?sec=<?=h($section)?>&lang=<?=$lang?>&edit=<?=(int)$r[$pk]?>">Editar</a><form method="post" onsubmit="return confirm('Excluir este registro?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="<?=h($pk)?>" value="<?=(int)$r[$pk]?>"><button type="submit" class="mini-btn danger">Excluir</button></form></div></td><?php endif;?></tr><?php endforeach;?></tbody></table></div></section></main>
<?php page_end(); ?>
